{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "구청 건물 주차장에서 임산부 할인 적용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "구청 건물 주차장은 시·자치구 및 그 소속기관 청사에 부설된 주차장에 해당하며, 그 관리자는 제7조제1항에 따른 주차요금 감면 차량에 대해 주차요금을 감면할 수 있다. 제7조제1항제7호의3은 「서울특별시 임산부 예우 및 지원에 관한 조례」에 따른 임산부가 탑승한 차량으로 임산부 앱카드 등 임산부임을 증명할 수 있는 서류를 제시한 경우 주차요금의 100분의 50을 할인하도록 정하고 있다. 따라서 구청 건물 주차장에서도 임산부 할인을 적용할 수 있고, 할인은 주차요금의 100분의 50이다.",
          "b_ids": "주차장:제23조의2, 주차장:제23조의2제1호, 주차장:제7조제1항제7호의3"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
